     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	/** Lista das mensagens "enviadas" (os envios ainda não saem de verdade). */
     7	public class Outbox {
     8	    private final List<Message> sent = new ArrayList<>();
     9	
    10	    public synchronized void send(Channel channel, String to, String subject, String body) {
    11	        sent.add(new Message(sent.size() + 1, channel, to, subject, body));
    12	    }
