     1	package com.marealta;
     2	
     3	import java.time.LocalDate;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	import java.util.Map;
     7	import java.util.TreeMap;
     8	
     9	public class ReservationService {
    10	    private final Map<Integer, Room> rooms = new TreeMap<>();
    11	    private final List<Reservation> reservations = new ArrayList<>();
    12	    private final List<ReservationListener> listeners = new ArrayList<>();
    13	
    14	    public ReservationService(List<Room> rooms) {
    15	        rooms.forEach(r -> this.rooms.put(r.number(), r));
    16	    }
    17	
    18	    public void addListener(ReservationListener listener) {
    19	        listeners.add(listener);
    20	    }
    21	
    22	    public List<Room> rooms() {
    23	        return List.copyOf(rooms.values());
    24	    }
    25	
    26	    public synchronized Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
    27	                                           LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan) {
    28	        Room room = rooms.get(roomNumber);
    29	        if (room == null) throw ApiException.roomNotFound(roomNumber);
    30	        if (guests > room.capacity()) throw ApiException.capacityExceeded(room);
    31	        boolean taken = reservations.stream().anyMatch(r -> r.room().equals(room)
    32	                && r.status() != ReservationStatus.CANCELLED && r.overlaps(checkIn, checkOut));
    33	        if (taken) throw ApiException.roomUnavailable(roomNumber);
    34	        Reservation reservation = new Reservation(reservations.size() + 1, room, guestName, guestEmail, guestCpf,
    35	                checkIn, checkOut, guests, plan);
    36	        reservations.add(reservation);
    37	        return reservation;
    38	    }
    39	
    40	    public synchronized Reservation get(String id) {
    41	        try {
    42	            int index = Integer.parseInt(id);
    43	            if (index >= 1 && index <= reservations.size()) return reservations.get(index - 1);
    44	        } catch (NumberFormatException ignored) {
    45	            // cai no não encontrado
    46	        }
    47	        throw ApiException.reservationNotFound(id);
    48	    }
    49	
    50	    public synchronized Reservation confirm(String id) {
    51	        Reservation r = get(id);
    52	        r.confirm();
    53	        listeners.forEach(l -> l.onConfirmed(r));
    54	        return r;
    55	    }
    56	
    57	    public synchronized Reservation cancel(String id) {
    58	        Reservation r = get(id);
    59	        boolean wasPaid = r.status().isPaid();
    60	        r.cancel();
    61	        if (wasPaid) listeners.forEach(l -> l.onPaidReservationCancelled(r));
    62	        return r;
    63	    }
    64	
    65	    public synchronized Reservation checkIn(String id) {
    66	        Reservation r = get(id);
    67	        r.registerCheckIn();
    68	        return r;
    69	    }
    70	
    71	    public synchronized Receipt checkOut(String id) {
    72	        Reservation r = get(id);
    73	        r.registerCheckOut();
    74	        return Receipt.of(r);
    75	    }
    76	
    77	    public synchronized Receipt document(String id) {
    78	        Reservation r = get(id);
    79	        if (!r.status().isPaid()) throw ApiException.notAllowed("Segunda via só existe para reserva paga");
    80	        return Receipt.of(r);
    81	    }
    82	
    83	    public synchronized List<Reservation> snapshot() {
    84	        return List.copyOf(reservations);
    85	    }
    86	}
