     1	package com.marealta;
     2	
     3	public class Main {
     4	    public static void main(String[] args) {
     5	        String port = System.getenv("PORT");
     6	        new App().start(port == null || port.isBlank() ? 7070 : Integer.parseInt(port.trim()));
     7	    }
     8	}
=== App.java
     1	package com.marealta;
     2	
     3	import com.fasterxml.jackson.databind.JsonNode;
     4	import com.fasterxml.jackson.databind.ObjectMapper;
     5	import com.fasterxml.jackson.databind.SerializationFeature;
     6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
     7	import io.javalin.Javalin;
     8	import io.javalin.http.Context;
     9	
    10	import java.time.LocalDate;
    11	import java.time.YearMonth;
    12	import java.time.format.DateTimeParseException;
    13	import java.util.List;
    14	import java.util.Map;
    15	
    16	public class App {
    17	    private static final ObjectMapper MAPPER = new ObjectMapper()
    18	            .registerModule(new JavaTimeModule())
    19	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    20	
    21	    private final ReservationService service;
    22	    private final Outbox outbox = new Outbox();
    23	    private final Reports reports;
    24	
    25	    public App() {
    26	        service = new ReservationService(List.of(
    27	                new Room(101, RoomType.STANDARD), new Room(102, RoomType.STANDARD),
    28	                new Room(201, RoomType.DELUXE), new Room(202, RoomType.DELUXE),
    29	                new Room(301, RoomType.SUITE)));
    30	        // Para avisar mais alguém (restaurante, transfer...), registre aqui um novo ReservationListener.
    31	        service.addListener(new GuestNotifier(outbox));
    32	        service.addListener(new HousekeepingNotifier(outbox));
    33	        service.addListener(new FinanceNotifier(outbox));
    34	        reports = new Reports(service);
    35	    }
    36	
    37	    public Javalin start(int port) {
    38	        Javalin app = Javalin.create();
    39	        app.exception(ApiException.class, (e, ctx) -> {
    40	            ctx.status(e.status());
    41	            json(ctx, Map.of("error", e.code(), "message", e.getMessage()));
    42	        });
    43	        app.get("/rooms", ctx -> json(ctx, service.rooms().stream().map(RoomView::of).toList()));
    44	        app.post("/reservations", ctx -> {
    45	            ctx.status(201);
    46	            json(ctx, ReservationView.of(create(ctx.body())));
    47	        });
    48	        app.get("/reservations/{id}", ctx -> json(ctx, ReservationView.of(service.get(ctx.pathParam("id")))));
    49	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, ReservationView.of(service.confirm(ctx.pathParam("id")))));
    50	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, ReservationView.of(service.cancel(ctx.pathParam("id")))));
    51	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, ReservationView.of(service.checkIn(ctx.pathParam("id")))));
    52	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, service.checkOut(ctx.pathParam("id"))));
    53	        app.get("/reservations/{id}/document", ctx -> json(ctx, service.document(ctx.pathParam("id"))));
    54	        app.get("/messages", ctx -> json(ctx, outbox.all()));
    55	        app.get("/reports/occupancy", ctx -> csv(ctx, reports.occupancy(parseDate(ctx.queryParam("date"), "date"))));
    56	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(parseMonth(ctx.queryParam("month")))));
    57	        return app.start(port);
    58	    }
    59	
    60	    private Reservation create(String body) {
    61	        JsonNode node;
    62	        try {
    63	            node = MAPPER.readTree(body);
    64	        } catch (Exception e) {
    65	            throw ApiException.invalid("Corpo não é um JSON válido");
    66	        }
    67	        if (node == null || !node.isObject()) throw ApiException.invalid("Corpo deve ser um objeto JSON");
    68	        int roomNumber = integer(node, "roomNumber");
    69	        String name = text(node, "guestName");
    70	        String email = text(node, "guestEmail");
    71	        String cpf = text(node, "guestCpf");
    72	        LocalDate checkIn = parseDate(text(node, "checkIn"), "checkIn");
    73	        LocalDate checkOut = parseDate(text(node, "checkOut"), "checkOut");
    74	        int guests = integer(node, "guests");
    75	        RatePlan plan;
    76	        try {
    77	            plan = RatePlan.valueOf(text(node, "ratePlan"));
    78	        } catch (IllegalArgumentException e) {
    79	            throw ApiException.invalid("ratePlan inválido");
    80	        }
    81	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("A saída deve ser depois da entrada");
    82	        if (guests < 1) throw ApiException.invalid("É preciso pelo menos um hóspede");
    83	        return service.create(roomNumber, name, email, cpf, checkIn, checkOut, guests, plan);
    84	    }
    85	
    86	    private static String text(JsonNode node, String field) {
    87	        JsonNode v = node.get(field);
    88	        if (v == null || !v.isTextual() || v.asText().isBlank()) throw ApiException.invalid("Campo obrigatório: " + field);
    89	        return v.asText();
    90	    }
    91	
    92	    private static int integer(JsonNode node, String field) {
    93	        JsonNode v = node.get(field);
    94	        if (v == null || !v.isIntegralNumber() || !v.canConvertToInt()) throw ApiException.invalid("Campo obrigatório (inteiro): " + field);
    95	        return v.asInt();
    96	    }
    97	
    98	    private static LocalDate parseDate(String value, String field) {
    99	        if (value == null) throw ApiException.invalid("Campo obrigatório: " + field);
   100	        try {
   101	            return LocalDate.parse(value);
   102	        } catch (DateTimeParseException e) {
   103	            throw ApiException.invalid("Data inválida em " + field + ", use AAAA-MM-DD");
   104	        }
   105	    }
   106	
   107	    private static YearMonth parseMonth(String value) {
   108	        if (value == null) throw ApiException.invalid("Campo obrigatório: month");
   109	        try {
   110	            return YearMonth.parse(value);
   111	        } catch (DateTimeParseException e) {
   112	            throw ApiException.invalid("Mês inválido, use AAAA-MM");
   113	        }
   114	    }
   115	
   116	    private static void json(Context ctx, Object body) {
   117	        try {
   118	            ctx.contentType("application/json").result(MAPPER.writeValueAsString(body));
   119	        } catch (Exception e) {
   120	            throw new IllegalStateException(e);
   121	        }
   122	    }
   123	
   124	    private static void csv(Context ctx, String body) {
   125	        ctx.contentType("text/csv; charset=utf-8").result(body);
   126	    }
   127	}

