    37	    public Javalin start(int port) {
    38	        Javalin app = Javalin.create();
    39	        app.exception(ApiException.class, (e, ctx) -> {
    40	            ctx.status(e.status());
    41	            json(ctx, Map.of("error", e.code(), "message", e.getMessage()));
    42	        });
    43	        app.get("/rooms", ctx -> json(ctx, service.rooms().stream().map(RoomView::of).toList()));
