    86	    private static String text(JsonNode node, String field) {
    87	        JsonNode v = node.get(field);
    88	        if (v == null || !v.isTextual() || v.asText().isBlank()) throw ApiException.invalid("Campo obrigatório: " + field);
    89	        return v.asText();
    90	    }
