    98	    private static LocalDate parseDate(String value, String field) {
    99	        if (value == null) throw ApiException.invalid("Campo obrigatório: " + field);
   100	        try {
   101	            return LocalDate.parse(value);
   102	        } catch (DateTimeParseException e) {
   103	            throw ApiException.invalid("Data inválida em " + field + ", use AAAA-MM-DD");
   104	        }
   105	    }
