    13	
    14	    public String occupancy(LocalDate night) {
    15	        List<Reservation> occupying = service.snapshot().stream()
    16	                .filter(r -> r.status().isPaid())
    17	                .filter(r -> !night.isBefore(r.checkIn()) && night.isBefore(r.checkOut()))
    18	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()))
    19	                .toList();
    20	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    21	        for (Reservation r : occupying) {
    22	            csv.append(r.room().number()).append(',').append(r.room().type()).append(',').append(r.id()).append(',')
    23	                    .append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    24	        }
    25	        csv.append("total,").append(occupying.size()).append('/').append(service.rooms().size()).append('\n');
    26	        return csv.toString();
    27	    }
    28	
    29	    public String revenue(YearMonth month) {
    30	        List<Reservation> rows = service.snapshot().stream()
    31	                .filter(r -> YearMonth.from(r.checkIn()).equals(month))
    32	                .filter(r -> r.retainedAmount().signum() > 0)
    33	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingInt(Reservation::id))
    34	                .toList();
    35	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    36	        BigDecimal sum = Money.ZERO;
    37	        for (Reservation r : rows) {
    38	            csv.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkIn()).append(',')
    39	                    .append(r.checkOut()).append(',').append(r.status()).append(',')
    40	                    .append(r.retainedAmount().toPlainString()).append('\n');
    41	            sum = sum.add(r.retainedAmount());
    42	        }
    43	        csv.append("total,").append(Money.round(sum).toPlainString()).append('\n');
