    23	
    24	    public Reservation(int id, Room room, String guestName, String guestEmail, String guestCpf,
    25	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    26	        this.id = id;
    27	        this.room = room;
    28	        this.guestName = guestName;
    29	        this.guestEmail = guestEmail;
    30	        this.guestCpf = guestCpf;
    31	        this.checkIn = checkIn;
    32	        this.checkOut = checkOut;
    33	        this.guests = guests;
    34	        this.ratePlan = ratePlan;
    35	        this.nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    36	        this.subtotal = Pricing.subtotal(room, checkIn, checkOut);
    37	        this.discount = ratePlan.discount(subtotal);
    38	        this.total = Money.round(subtotal.subtract(discount));
    39	    }
