    48	        require(status == ReservationStatus.CONFIRMED, "Só é possível fazer check-in de uma reserva confirmada");
    49	        status = ReservationStatus.CHECKED_IN;
    50	    }
    51	
    52	    public void registerCheckOut() {
    53	        require(status == ReservationStatus.CHECKED_IN, "Só é possível fazer check-out de uma reserva com check-in");
    54	        status = ReservationStatus.CHECKED_OUT;
