     6	/** Cálculo da soma das noites, com acréscimo de alta temporada. */
     7	public final class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    private Pricing() {}
    11	
    12	    /** Alta temporada: 15/12 a fim de fevereiro e julho inteiro. */
    13	    public static boolean isHighSeason(LocalDate night) {
    14	        int month = night.getMonthValue();
    15	        return month == 1 || month == 2 || month == 7 || (month == 12 && night.getDayOfMonth() >= 15);
    16	    }
    17	
    18	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    19	        BigDecimal rate = room.type().nightlyRate();
    20	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    21	    }
    22	
    23	    public static BigDecimal subtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    24	        BigDecimal sum = Money.ZERO;
    25	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    26	            sum = Money.round(sum.add(nightPrice(room, night)));
    27	        }
    28	        return sum;
    29	    }
    30	}
